        "content_preview": "# General Design Critique Checklist\n\n作品集自查清单包括：是否明确目标用户，是否说明核心痛点，是否有调研证据，是否解释设计机会，是否展示方案迭代，是否把最终效果和前文问题对应起来。每个项目至少需要一页说明“为什么这样设计”，否则读者只能看到结果图。",
