        "content_preview": "# Portfolio Page Structure\n\n作品集页面结构建议采用问题、证据、洞察、策略、方案、验证的顺序。每页不要只放最终图，而要说明这一页解决叙事中的哪一个问题。背景页讲清用户和场景，调研页展示证据，痛点页提炼判断，概念页说明选择，发展页展示迭代，最终页展示完成度。",
