        "source_folder": "data/inbox",
        "content_preview": "# Reader Design Sketch Panel Layout\n\n草图说明记录了阅读器主界面的三种布局：单栏沉浸阅读、双栏摘录侧边栏、底部轻量工具条。草图讨论重点是如何避免工具遮挡正文，同时让用户能快速保存段落。当前方案倾向于默认隐藏工具，只在选中文本时出现。该资料适合 development 阶段，用来展示从阅读痛点到界面结构的推敲过程。",
