        "content_preview": "# Design Student Notes\n\n设计学生做作品集时经常遇到资料混乱的问题：草图、灵感图、调研记录、老师反馈和页面文案分散在不同文件夹里。\n\n这些资料如果不能及时回收，就很难形成清晰的作品集叙事。当前需要一个工具帮助整理项目逻辑、标记资料类型，并提示哪些内容可以进入作品集页面。",
