        "modified_time": "2026-05-06T22:36:34",
        "source_folder": "data/inbox",
        "content_preview": "# Portfolio Design Opportunity\n\n设计机会是从证据到方案之间的桥。它不等于功能清单，而是说明设计可以在哪个环节改变用户行为或降低成本。例如低干扰阅读的机会不是“增加专注模式”，而是减少阅读、摘录、整理之间的切换负担。该资料可用于 concept 阶段的写作。",
