        "filename": "reader-design-idea-focus-session.md",
        "path": "data/inbox/reader-design-idea-focus-session.md",
        "extension": "md",
        "size": 402,
        "modified_time": "2026-05-06T22:36:33",
        "source_folder": "data/inbox",
        "content_preview": "# Reader Design Idea Focus Session\n\n功能设想：低干扰阅读会话。用户开始阅读前设置 20 分钟目标，期间系统隐藏非必要入口，只保留进度、书签和退出。会话结束后，系统自动生成本次阅读的摘录列表和待整理问题。这个想法不是最终方案，但可以作为 concept 阶段资料，用于说明设计机会如何转成产品功能。",
