        "content_preview": "# Portfolio Project Narrative\n\n项目叙事不应该从“我做了一个产品”开始，而应从用户为什么需要它开始。好的叙事会让读者看到设计机会如何出现，方案如何被约束，以及最终表达如何回应前面的证据。该资料适合 general 项目，用于生成作品集草稿和检查页面顺序。",
