        "source_folder": "data/examples",
        "content_preview": "# Reader Design User Interview Commute\n\n用户访谈记录聚焦通勤阅读。受访者描述在地铁上读长文章时，最容易被社交软件和系统通知打断。另一个问题是站立状态下单手操作不稳定，翻页、划线和保存句子都容易误触。用户希望阅读器能提供专注模式、稍后整理和轻量摘录。这个资料适合作为 reader-design 的 research 证据，也能支撑用户痛点页面。",
