        "content_preview": "# Portfolio Pain Point Analysis\n\n痛点分析需要避免空泛词，例如“不方便”“体验不好”。更有效的写法是描述用户在什么场景、为了完成什么任务、遇到什么阻碍、造成什么后果。用户痛点最好能对应访谈原话、行为观察或竞品差异。该资料可用于作品集痛点页的文案检查。",
