        "source_folder": "data/inbox",
        "content_preview": "# Reader Design Competitor Kindle Notion\n\n竞品分析比较了 Kindle、Notion、浏览器阅读模式和稍后读工具。Kindle 的沉浸感强，但整理链路较弱；Notion 适合整理，但阅读体验偏编辑器；浏览器阅读模式降低噪音，但缺少长期资料管理。DesignMate 中这份资料可归为 competitor，用于说明阅读器方案的机会：在低干扰阅读和结构化回收之间建立更短路径。",
