        "content_preview": "Reader Design Draft Portfolio Page\n\n页面草稿：本项目从通勤阅读中的打断问题出发，重新组织阅读、摘录和回顾三个动作。设计机会在于降低用户从阅读状态切换到整理状态的成本。页面需要补充用户访谈证据、竞品对比图和草图迭代，否则论点会显得像功能介绍。",
