        "source_folder": "data/examples",
        "content_preview": "# Info Center Space Research\n\n图信中心空间调研记录了入口、咨询台、自习区、借阅区和开放讨论区的关系。观察发现，新用户进入后常停在入口附近寻找导览信息，高峰时咨询台周边会形成短暂停留。空间问题不是单纯面积不足，而是信息提示、动线组织和功能分区之间缺少连续性。该资料适合 info-center 的 research 阶段。",
