        "source_folder": "data/inbox",
        "content_preview": "# Info Center Circulation Flow\n\n空间动线分析关注入口到咨询台、书架、自习区和出口之间的路径。现有问题是部分路径交叉导致停留和通行互相干扰，尤其在借还书高峰时更明显。优化方向是让快速路径更短，让深度停留区域减少穿越。这个资料适合图信中心作品集中的发展页，用来展示动线推敲。",
