        "content_preview": "Info Center Draft Service Touchpoints\n\n图信中心服务触点包括入口导视、咨询台、检索终端、书架节点、自习座位和讨论室预约入口。当前草稿需要说明每个触点解决的用户问题。尤其是入口导视和咨询台之间的关系，应当通过动线观察来证明，而不是只用平面布局表达。",
