        "source_folder": "data/inbox",
        "content_preview": "# Info Center Functional Zoning\n\n功能分区设想把图信中心划分为快速服务区、安静阅读区、资料检索区和协作讨论区。分区依据不是装饰风格，而是用户行为强度和噪音容忍度。快速服务靠近入口，安静阅读远离主通道，讨论区需要半开放边界。该资料可用于 concept 和 development 阶段，说明空间策略如何回应调研。",
