        "source_folder": "data/inbox",
        "content_preview": "# Info Center User Behavior\n\n用户行为观察显示，图信中心使用者主要有三类：快速借还书的人、寻找安静座位的人、需要小组讨论的人。三类用户的停留时间和路径差异明显。快速借还书希望路径直接，自习用户关注噪音和座位可见性，讨论用户需要可预约空间。该资料可以转化为用户分层和痛点分析页面。",
