        "content_preview": "# Thesis Dual City Commute\n\n双城通勤资料关注居住地和工作地分离带来的时间成本、交通依赖和生活节奏变化。以廊坊和北京之间的通勤为例，通勤人群往往需要在住房成本、通勤时间和公共服务之间做取舍。该资料属于 thesis，可用于论文背景，也可能为城市空间结构研究提供案例。",
