        "content_preview": "# Thesis Langfang Urban Structure\n\n廊坊城市空间结构资料关注其位于北京和天津之间的区位特点。城市发展受到区域交通、产业联系和居住外溢影响。对于双城通勤研究，廊坊不是单独城市样本，而是区域网络中的节点。该资料适合论文 background 阶段，后续需要补充数据来源。",
