        "content_preview": "# Thesis Research Method Note\n\n论文研究方法需要结合文献阅读、空间数据、交通联系和访谈材料。对于双城通勤主题，只看宏观交通数据会忽略个人体验，只做访谈又难以解释城市结构。较稳妥的方法是先建立区域背景，再选择通勤人群进行半结构访谈。",
