        "content_preview": "# Thesis Transport Connection\n\n交通联系资料记录城际铁路、高速路和公交接驳对双城通勤的影响。单一交通方式不能解释全部体验，换乘、候车、末端接驳和票价都会影响通勤可持续性。该资料可作为论文中的分析框架，也能帮助后续建立通勤路径图。",
